const dialog=document.querySelector('#form-dialog');const dialogTitle=document.querySelector('#dialog-title');document.querySelectorAll('[data-form-name]').forEach(button=>{button.addEventListener('click',()=>{dialogTitle.textContent=`${button.dataset.formName}: link em breve`;dialog.showModal()})});document.querySelectorAll('.dialog-close,.dialog-confirm').forEach(button=>{button.addEventListener('click',()=>dialog.close())});dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});
